import datetime
import os

LOG_FILE_PATH = 'ciel_workspace/heartbeat.log'

def append_heartbeat_log():
    """Append a timestamped heartbeat line to the log file."""
    try:
        timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_line = f"fallback heartbeat - [{timestamp}]"

        log_dir = os.path.dirname(LOG_FILE_PATH)
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)

        with open(LOG_FILE_PATH, 'a') as f:
            f.write(log_line + '\n')
    except IOError as e:
        print(f"Error writing to log file '{LOG_FILE_PATH}': {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    append_heartbeat_log()

import platform, subprocess, ctypes, datetime

def get_uptime_seconds():
    s = platform.system()
    if s == "Linux":
        with open("/proc/uptime") as f: return float(f.readline().split()[0])
    elif s == "Darwin":
        out = subprocess.check_output(["sysctl", "-n", "kern.boottime"]).decode()
        boot = int(out.split("sec = ")[1].split(",")[0])
        return datetime.datetime.now().timestamp() - boot
    elif s == "Windows":
        return ctypes.windll.kernel32.GetTickCount64() / 1000.0
    raise NotImplementedError(f"Unsupported OS: {s}")

def format_uptime(sec):
    d, h = divmod(sec, 86400)
    h, m = divmod(h, 3600)
    m, s = divmod(m, 60)
    p = []
    if d: p.append(f"{int(d)}d")
    if h: p.append(f"{int(h)}h")
    if m: p.append(f"{int(m)}m")
    p.append(f"{int(s)}s")
    return " ".join(p)

try:
    print(f"System Uptime: {format_uptime(get_uptime_seconds())}")
except Exception as e:
    print(f"Error: {e}")
